    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """

    def decorator(method):
        if condition is not None:
            # Condition-based synchronization for stampede protection
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(self, *args, **kwargs)
                # Get the condition object
                cond = condition(self) if callable(condition) else condition
                with cond:
                    try:
                        return c[k]
                    except KeyError:
                        pass
                    # Cache miss - check if someone else is computing it
                    if not hasattr(c, '_in_progress'):
                        c._in_progress = set()
                    if k in c._in_progress:
                        cond.wait()
                        try:
                            return c[k]
                        except KeyError:
                            pass
                    c._in_progress.add(k)
                v = method(self, *args, **kwargs)
                with cond:
                    try:
                        c[k] = v
                    except ValueError:
                        c._in_progress.discard(k)
                        cond.notify_all()
                        return v
                    c._in_progress.discard(k)
                    cond.notify_all()
                    return v

            def clear(self):
                c = cache(self)
                if c is not None:
                    with (condition(self) if callable(condition) else condition):
                        c.clear()
                        if hasattr(c, '_in_progress'):
                            c._in_progress.clear()

        elif lock is None:

            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(self, *args, **kwargs)
                try:
